<?php
$pageTitle='Pedidos web | Ltecobike'; require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/../includes/auth.php'; requiereModulo('ecommerce'); require_once __DIR__.'/../includes/helpers.php';
$pedidosService = new \Lteco\Application\Ecommerce\PedidoPanelService(new \Lteco\Infrastructure\Db\Connection($pdo));
$error='';$idUsuario=(int)(usuarioActual()['IdUsuario']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){try{requirePost();verifyCsrfOrFail();$accion=(string)($_POST['accion']??'estado');if($accion==='confirmar_efectivo'){$pedidosService->confirmarPagoEfectivo((int)($_POST['id']??0),$idUsuario);}elseif($accion==='reembolso'){$pedidosService->solicitarReembolso((int)($_POST['id']??0),$idUsuario,(string)($_POST['motivo']??''));}elseif($accion==='privacidad'){$pedidosService->resolverSolicitudPrivacidad((int)($_POST['id']??0),$idUsuario,(string)($_POST['estado']??''),(string)($_POST['respuesta']??''));}else{$pedidosService->actualizarEstado((int)($_POST['id']??0),(string)($_POST['estado']??''),$idUsuario,(string)($_POST['receptor']??''),(string)($_POST['evidencia']??''));}}catch(Throwable $e){$error=$e->getMessage();$pedidosService->registrarErrorOperativo((int)($_POST['id']??0),$idUsuario,(string)($_POST['accion']??'estado'),$error);}}
$filtros=['estado'=>(string)($_GET['estado']??''),'buscar'=>(string)($_GET['buscar']??'')];$pedidos=$pedidosService->listar(200,$filtros);$metricas=$pedidosService->metricas();$solicitudesPrivacidad=$pedidosService->listarSolicitudesPrivacidad();
require __DIR__.'/../includes/header.php'; require __DIR__.'/../includes/sidebar.php'; ?>
<script>document.addEventListener('DOMContentLoaded',()=>{const p=document.querySelector('.topbar .subtle');if(p){const a=document.createElement('a');a.href='privacidad.php';a.textContent=' Gestionar privacidad de clientes';p.appendChild(a)}});</script>
<main class="main"><div class="topbar"><div><h1>Pedidos web</h1><p class="subtle">Pagos, preparación y entrega de compras online. Tocá el número de pedido para abrir su ficha completa.</p></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const ids=<?=json_encode(array_map('intval',array_column($pedidos,'IdPedido')))?>;document.querySelector('.table-wrap table')?.querySelectorAll('tbody tr').forEach((row,index)=>{const strong=row.querySelector('td:first-child strong');const id=ids[index];if(id&&strong){const a=document.createElement('a');a.href='ver.php?id='+encodeURIComponent(id);a.textContent=strong.textContent;strong.textContent='';strong.appendChild(a)}})});</script><?php if($error):?><div class="notice notice--error"><?=h($error,'')?></div><?php endif?>
<div class="cards"><div class="card"><small>Pendientes de pago</small><strong><?=count(array_filter($pedidos,fn($p)=>in_array($p['Estado'],['PendientePago','PagoEnRevision'],true)))?></strong></div><div class="card"><small>Pagados / preparando</small><strong><?=count(array_filter($pedidos,fn($p)=>in_array($p['Estado'],['Pagado','Preparando','Listo'],true)))?></strong></div><div class="card"><small>Checkout iniciados · 30 días</small><strong><?=(int)($metricas['checkout_iniciado']??0)?></strong></div><div class="card"><small>Pedidos creados · 30 días</small><strong><?=(int)($metricas['pedido_creado']??0)?></strong></div></div>
<form method="get" class="filters"><input name="buscar" value="<?=h($filtros['buscar'],'')?>" placeholder="Pedido, nombre o correo"><select name="estado"><option value="">Todos los estados</option><?php foreach(['PendientePago','PagoEnRevision','Pagado','Preparando','Listo','Entregado','Cancelado','Vencido','ReembolsoPendiente','Reembolsado','ExcepcionPagoSinStock'] as$estado):?><option value="<?=$estado?>" <?=$filtros['estado']===$estado?'selected':''?>><?=$estado?></option><?php endforeach?></select><button class="btn-secondary">Filtrar</button></form>
<div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Unidad</th><th>Total</th><th>Pago</th><th>Entrega</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php if(!$pedidos):?><tr><td colspan="8">Todavía no hay pedidos web.</td></tr><?php endif?><?php foreach($pedidos as $p):?><?php $next=['Pagado'=>'Preparando','Preparando'=>'Listo'][$p['Estado']]??null; ?><tr><td><strong><?=h($p['NumeroPedido'],'')?></strong><br><small><?=h(date('d/m/Y H:i',strtotime($p['CreadoEn'])),'')?></small></td><td><?=h($p['Nombre'].' '.$p['Apellido'],'')?><br><small><?=h($p['Telefono'],'')?> · <?=h($p['Correo'],'')?></small></td><td><?=h($p['Items'],'')?><?php if(!empty($p['NumerosMotor'])):?><br><small>Motor: <?=h($p['NumerosMotor'],'')?></small><?php endif?></td><td><?=h($p['Moneda'].' '.number_format((float)$p['Total'],2,',','.'),'')?></td><td><?=h($p['EstadoPago'],'')?></td><td><?=h($p['Entrega'],'')?><?php if(!empty($p['EntregadoEn'])):?><br><small>Entregado <?=h(date('d/m/Y H:i',strtotime($p['EntregadoEn'])),'')?> a <?=h($p['ReceptorEntrega']??'','')?></small><?php endif?></td><td><?=h($p['Estado'],'')?></td><td><?php if($p['ProveedorPago']==='cash'&&$p['Estado']==='PagoEnRevision'):?><form method="post" class="shop-form" onsubmit="return confirm('¿Confirmás que recibiste el total en efectivo? Esto creará la venta.');"><?=csrfInput()?><input type="hidden" name="accion" value="confirmar_efectivo"><input type="hidden" name="id" value="<?=(int)$p['IdPedido']?>"><button class="btn-primary btn-small">Confirmar efectivo</button></form><?php elseif($next):?><form method="post" class="shop-form"><?=csrfInput()?><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=(int)$p['IdPedido']?>"><input type="hidden" name="estado" value="<?=h($next,'')?>"><button class="btn-secondary btn-small">Marcar <?=h(strtolower($next),'')?></button></form><?php else:?><a class="btn-secondary btn-small" href="ver.php?id=<?=(int)$p['IdPedido']?>">Gestionar</a><?php endif?></td></tr><?php endforeach?></tbody></table></div>
<div class="topbar"><div><h2>Solicitudes de privacidad</h2><p class="subtle">Acceso, corrección y supresión solicitados por clientes.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Cliente</th><th>Tipo</th><th>Detalle</th><th>Estado</th><th>Gestión</th></tr></thead><tbody><?php if(!$solicitudesPrivacidad):?><tr><td colspan="5">No hay solicitudes.</td></tr><?php endif?><?php foreach($solicitudesPrivacidad as$s):?><tr><td><?=h(trim($s['Nombre'].' '.($s['Apellido']??'')),'')?><br><small><?=h($s['Correo'],'')?></small></td><td><?=h($s['Tipo'],'')?></td><td><?=h($s['Detalle']??'','')?></td><td><?=h($s['Estado'],'')?></td><td><form method="post" class="shop-form"><?=csrfInput()?><input type="hidden" name="accion" value="privacidad"><input type="hidden" name="id" value="<?=(int)$s['IdSolicitud']?>"><select name="estado"><option value="EnProceso">En proceso</option><option value="Resuelta">Resuelta</option><option value="Rechazada">Rechazada</option></select><input name="respuesta" placeholder="Respuesta o resolución"><button class="btn-secondary btn-small">Actualizar</button></form></td></tr><?php endforeach?></tbody></table></div></main><?php require __DIR__.'/../includes/footer.php';?>
